var my = +v('my') || 50, goal = +v('goal') || 50, mo = Math.max(0, +v('months') || 0);
var diff = my - goal + mo * 0.6;
var p = 1 / (1 + Math.exp(-diff / 4)) * 100; p = Math.max(2, Math.min(97, p));
var h = my + mo * 0.6, hc = Math.max(0, Math.min(100, h)), gc = Math.max(0, Math.min(100, goal));
Crowd.distribution(el, { n: 100, mean: 50, sd: 10, you: hc, line: gc, lineLabel: '志望校 ' + goal,
  title: '本番の受験生100人を偏差値で並べると',
  tick: function (x) { return x.toFixed(0); },
  final: function (rk, n, above) { return '今の' + my + '＋あと' + mo + 'ヶ月の伸びで、本番は偏差値 約' + h.toFixed(1) + '（100人中 ' + rk + '位）。志望校' + goal + '以上は ' + above + '人（緑の点）で、合格可能性は約' + Math.round(p) + '%。'; } });
